import{_ as t,o,c as a,a2 as s}from"./chunks/framework.CfwCq2QB.js";const r="/dev-go-docs/shots/0.2.3/en/light/cors-card.png",u=JSON.parse('{"title":"CORS debugging","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/cors.md","filePath":"en/features/cors.md"}'),n={name:"en/features/cors.md"};function i(d,e,l,c,h,g){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="cors-debugging" tabindex="-1">CORS debugging <a class="header-anchor" href="#cors-debugging" aria-label="Permalink to &quot;CORS debugging&quot;">​</a></h1><p>In one line: a toggle that adds cross-origin response headers to the page&#39;s XHR / fetch responses — convenient for local development.</p><h2 id="when-you-need-it" tabindex="-1">When you need it <a class="header-anchor" href="#when-you-need-it" aria-label="Permalink to &quot;When you need it&quot;">​</a></h2><p>The classic local-dev error: your frontend on <code>localhost:5173</code> requests an API on another domain, and the browser blocks the response because it&#39;s missing <code>Access-Control-Allow-Origin</code>. The request actually succeeded — the page just can&#39;t read it.</p><p>Flip this switch and DevGo adds the missing CORS headers to the page&#39;s XHR / fetch responses. The frontend works without code changes or a dev proxy — unblock yourself first, fix the server later.</p><h2 id="how-to-enable" tabindex="-1">How to enable <a class="header-anchor" href="#how-to-enable" aria-label="Permalink to &quot;How to enable&quot;">​</a></h2><p>Popup&#39;s Network page → &quot;Disable CORS restrictions&quot;. <strong>Refresh the page</strong> after toggling.</p><img src="'+r+'" alt="The &#39;Disable CORS restrictions&#39; card: toggle and notes"><p><em>The &quot;Disable CORS restrictions&quot; card — refresh the page after toggling; see the limits below for what it can&#39;t fix.</em></p><h2 id="limits-and-caveats" tabindex="-1">Limits and caveats <a class="header-anchor" href="#limits-and-caveats" aria-label="Permalink to &quot;Limits and caveats&quot;">​</a></h2><ul><li>For <strong>local development and debugging</strong> only — don&#39;t leave it on while browsing: it weakens the browser&#39;s same-origin protection</li><li>It can&#39;t fix: servers that reject OPTIONS preflights outright, credentialed (Cookie) requests, CSP restrictions, or mixed content (HTTPS pages requesting HTTP endpoints) — those need server-side or page-side fixes</li><li>Independent of real IP protection and proxy modes; can be used together with either</li></ul>',11)])])}const f=t(n,[["render",i]]);export{u as __pageData,f as default};
